{% set company = frappe.get_doc('Company', doc.company) %}
{% set currency = frappe.db.get_value('Currency', doc.currency, 'symbol') or doc.currency or 'YER' %}
{% set branding_logo = frappe.db.get_single_value('POS Branding Settings', 'primary_logo') if frappe.db.exists('DocType', 'POS Branding Settings') else '' %}
{% set logo = company.company_logo or branding_logo or '' %}
{% set tax_id = company.tax_id or '' %}
{% set tax_amount = doc.total_taxes_and_charges or 0 %}
{% set issue_time = (doc.posting_time|string).split('.')[0] if doc.posting_time else '' %}
{% set timestamp = doc.posting_date|string + 'T' + (doc.posting_time|string if doc.posting_time else '00:00:00') %}
{% set grand_total_text = '%.2f'|format(doc.grand_total or 0) %}
{% set tax_total_text = '%.2f'|format(tax_amount) %}
{% set qr = generate_zatca_qr_dataurl(company.company_name or doc.company, tax_id, timestamp, grand_total_text, tax_total_text) if tax_id else '' %}
{% set outstanding = doc.outstanding_amount or 0 %}
<style>
@page { size:A4; margin:10mm; }
* { box-sizing:border-box; } body { background:#fff; color:#172033; font-family:'DejaVu Sans','Noto Sans Arabic',Arial,sans-serif; font-size:11px; line-height:1.55; }
.invoice { direction:rtl; max-width:820px; margin:0 auto; } .top-accent { background:linear-gradient(90deg,#f59e0b,#14b8a6,#075e54); border-radius:18px 18px 0 0; height:7px; }
.brand-panel { align-items:center; background:#075e54; color:#fff; display:flex; gap:18px; justify-content:space-between; padding:25px 28px; }.brand { align-items:center; display:flex; gap:15px; }.logo { background:#fff; border-radius:12px; box-shadow:0 5px 14px rgba(0,0,0,.16); max-height:64px; max-width:132px; object-fit:contain; padding:6px; }.brand-name { font-size:25px; font-weight:800; margin:0; }.brand-contact { color:#d1fae5; font-size:10px; margin:4px 0 0; }.document-badge { border:1px solid #99f6e4; border-radius:12px; min-width:126px; padding:8px 12px; text-align:center; }.document-badge b { display:block; font-size:12px; }.document-badge small { color:#ccfbf1; font-size:9px; }
.paper { border:1px solid #d9e3e5; border-radius:0 0 18px 18px; padding:24px 28px 26px; }.meta { display:grid; gap:12px; grid-template-columns:repeat(3,1fr); margin-bottom:16px; }.meta-card { background:#f7faf9; border:1px solid #e1ecec; border-radius:10px; min-height:60px; padding:10px 12px; }.label { color:#64748b; display:block; font-size:9px; letter-spacing:.15px; margin-bottom:3px; }.value { direction:ltr; font-weight:800; }.customer { align-items:center; background:#fffbeb; border:1px solid #fde68a; border-radius:10px; display:flex; justify-content:space-between; margin-bottom:19px; padding:11px 13px; }.customer strong { font-size:13px; }.customer .muted { color:#7c6a33; font-size:10px; }
.table { border-collapse:separate; border-spacing:0; width:100%; }.table th { background:#075e54; color:#fff; font-size:10px; font-weight:700; padding:10px 9px; text-align:right; }.table th:first-child { border-radius:0 8px 8px 0; }.table th:last-child { border-radius:8px 0 0 8px; }.table td { border-bottom:1px solid #e6edef; padding:11px 9px; vertical-align:top; }.table tr:nth-child(even) td { background:#fbfdfd; }.amount { direction:ltr; font-weight:800; text-align:left; white-space:nowrap; }.muted { color:#64748b; font-size:10px; }.serial { color:#0f766e; font-family:monospace; font-size:10px; margin-top:3px; }.discount { color:#b45309; font-size:10px; margin-top:3px; }
.summary { display:grid; gap:18px; grid-template-columns:1fr 310px; margin-top:22px; }.panel { border:1px solid #e1ecec; border-radius:12px; padding:14px; }.panel-title { color:#075e54; font-size:12px; font-weight:800; margin:0 0 8px; }.line { align-items:center; display:flex; justify-content:space-between; gap:12px; padding:5px 0; }.line + .line { border-top:1px solid #edf2f2; }.total { background:#ecfdf5; border:1px solid #a7f3d0; border-radius:9px; color:#065f46; font-size:17px; font-weight:900; margin-top:9px; padding:10px; }.payment-status { border-radius:7px; display:inline-block; font-size:10px; font-weight:800; padding:4px 8px; }.paid { background:#dcfce7; color:#166534; }.due { background:#fee2e2; color:#b91c1c; }
.footer { align-items:center; border-top:1px dashed #b6c8c8; display:flex; gap:20px; justify-content:space-between; margin-top:24px; padding-top:16px; }.thanks { color:#075e54; font-size:16px; font-weight:900; margin-bottom:2px; }.footer-copy { color:#64748b; font-size:10px; }.qr-box { align-items:center; background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; display:flex; gap:7px; padding:7px; }.qr { height:78px; width:78px; }.qr-box small { color:#64748b; font-size:8px; max-width:82px; }
@media print { .invoice { max-width:none; }.paper { border-color:#cbd5d8; } } @media (max-width:600px) { .meta,.summary { grid-template-columns:1fr; }.brand-panel,.footer { align-items:flex-start; flex-direction:column; }.table { font-size:9px; } }
</style>
<div class="invoice">
 <div class="top-accent"></div>
 <header class="brand-panel"><div class="brand">{% if logo %}<img class="logo" src="{{ logo }}" alt="{{ company.company_name or doc.company }}">{% endif %}<div><h1 class="brand-name">{{ company.company_name or doc.company }}</h1><p class="brand-contact">{% if company.phone_no %}{{ company.phone_no }}{% endif %}{% if company.phone_no and company.website %} · {% endif %}{% if company.website %}{{ company.website }}{% endif %}</p></div></div><div class="document-badge"><b>{% if doc.is_return %}إشعار مرتجع{% else %}فاتورة مبيعات{% endif %}</b><small>{% if doc.is_return %}RETURN NOTE{% else %}SALES INVOICE{% endif %}</small></div></header>
 <main class="paper">
  <section class="meta"><div class="meta-card"><span class="label">رقم الفاتورة</span><span class="value">{{ doc.name }}</span></div><div class="meta-card"><span class="label">تاريخ ووقت الإصدار</span><span class="value">{{ doc.posting_date }}{% if issue_time %} · {{ issue_time }}{% endif %}</span></div><div class="meta-card"><span class="label">الرقم الضريبي</span><span class="value">{{ tax_id or '—' }}</span></div></section>
  <section class="customer"><div><span class="label">بيانات العميل</span><strong>{{ doc.customer_name or doc.customer or 'عميل نقدي' }}</strong>{% if doc.contact_mobile %}<span class="muted"> · {{ doc.contact_mobile }}</span>{% endif %}</div><span class="payment-status {% if outstanding > 0 %}due{% else %}paid{% endif %}">{% if outstanding > 0 %}متبقي {{ '%.2f'|format(outstanding) }} {{ currency }}{% else %}مدفوعة بالكامل{% endif %}</span></section>
  <table class="table"><thead><tr><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>{% for item in doc.items %}<tr><td><strong>{{ item.item_name }}</strong>{% if item.item_code and item.item_code != item.item_name %}<div class="muted">{{ item.item_code }}</div>{% endif %}{% if item.serial_no %}<div class="serial">IMEI / S/N: {{ item.serial_no|replace('\n', ', ') }}</div>{% endif %}{% if item.discount_amount %}<div class="discount">خصم: {{ '%.2f'|format(item.discount_amount) }} {{ currency }}</div>{% endif %}</td><td class="amount">{{ '%.2f'|format(item.qty or 0) }} {{ item.uom or '' }}</td><td class="amount">{{ '%.2f'|format(item.rate or 0) }} {{ currency }}</td><td class="amount">{{ '%.2f'|format(item.amount or 0) }} {{ currency }}</td></tr>{% endfor %}</tbody></table>
  <section class="summary"><div class="panel"><h3 class="panel-title">تفاصيل الدفع</h3>{% if doc.payments %}{% for payment in doc.payments if payment.amount %}<div class="line"><span>{{ payment.mode_of_payment }}</span><strong class="amount">{{ '%.2f'|format(payment.amount) }} {{ currency }}</strong></div>{% endfor %}{% else %}<div class="muted">لا توجد تفاصيل دفع مسجلة.</div>{% endif %}{% if doc.change_amount %}<div class="line"><span>المبلغ المعاد</span><strong class="amount">{{ '%.2f'|format(doc.change_amount) }} {{ currency }}</strong></div>{% endif %}</div><div class="panel"><h3 class="panel-title">ملخص الفاتورة</h3><div class="line"><span>الإجمالي قبل الضريبة</span><strong class="amount">{{ '%.2f'|format(doc.net_total or 0) }} {{ currency }}</strong></div>{% if tax_amount %}<div class="line"><span>الضريبة</span><strong class="amount">{{ '%.2f'|format(tax_amount) }} {{ currency }}</strong></div>{% endif %}{% if doc.discount_amount %}<div class="line"><span>خصم الفاتورة</span><strong class="amount">- {{ '%.2f'|format(doc.discount_amount) }} {{ currency }}</strong></div>{% endif %}<div class="line total"><span>الإجمالي المستحق</span><span class="amount">{{ grand_total_text }} {{ currency }}</span></div></div></section>
  <footer class="footer"><div><div class="thanks">شكرًا لثقتكم بنا</div><div class="footer-copy">هذه نسخة إلكترونية رسمية من فاتورتكم. احتفظ بها للرجوع إليها.</div>{% if company.email %}<div class="footer-copy">{{ company.email }}</div>{% endif %}</div>{% if qr %}<div class="qr-box"><img class="qr" src="{{ qr }}" alt="رمز QR للفاتورة"><small>امسح الرمز للتحقق من بيانات الفاتورة الضريبية.</small></div>{% endif %}</footer>
 </main>
</div>
